let $in := {
  "foo": {
    "baz": [ { "bar": "a", "bam": "b", "boo": "c" }, { "bar": "d", "bam": "e", "boo": "f" } ],
    "qux": [ "zero" ]
  }
}
return $in/foo ! [ (array { baz/*/not_there ! jvalue() }[array:size(.) > 0] otherwise array { baz/*/bar ! jvalue() }), qux/1 ! jvalue() ]

let $in := {
  "foo": {
    "bar": { "baz": "subkey" },
    "other": { "baz": "subkey" },
    "other2": { "baz": "subkey" },
    "other3": { "notbaz": [ "a", "b", "c" ] },
    "other4": { "notbaz": [ "a", "b", "c" ] }
  }
} => jtree()
return $in ! jtree({ "a": foo/bar ! jvalue(), "b": foo/other ! jvalue() })/*/baz

let $in := {
  "foo": {
    "bar": { "baz": "one" },
    "other": { "baz": "two" },
    "other2": { "baz": "three" },
    "other3": { "notbaz": [ "a", "b", "c" ] },
    "other4": { "notbaz": [ "d", "e", "f" ] }
  }
} => jtree()
return $in ! jtree([ foo/bar ! jvalue(), foo/other ! jvalue() ])/1

let $in := {
  "foo": {
    "bar": { "baz": "one" },
    "other": { "baz": "two" },
    "other2": { "baz": "three" },
    "other3": { "notbaz": [ "a", "b", "c" ] },
    "other4": { "notbaz": [ "d", "e", "f" ] }
  }
} => jtree()
return $in ! jtree({ "a": foo/bar ! jvalue(), "b": foo/other ! jvalue() })/a

let $in := {
  "foo": {
    "bar": { "baz": "one" },
    "other": { "baz": "two" },
    "other2": { "baz": "three" },
    "other3": { "notbaz": [ "a", "b", "c" ] },
    "other4": { "notbaz": [ "d", "e", "f" ] }
  }
} => jtree()
return $in ! jtree({ "a": foo/bar ! jvalue(), "b": foo/other ! jvalue() })/b

let $in := {
  "foo": [
    { "bar": [ { "baz": "one" }, { "baz": "two" } ] },
    { "bar": [ { "baz": "three" }, { "baz": "four" } ] }
  ]
}
return $in/foo ! jtree(array { * ! bar ! array { * ! jvalue() } })/1/1

let $in := {
  "foo": [
    { "bar": [ { "kind": "basic" }, { "kind": "intermediate" } ] },
    { "bar": [ { "kind": "advanced" }, { "kind": "expert" } ] },
    { "bar": "string" }
  ]
}
return $in/foo ! array { * ! jnode(bar, array(*)) ! array { * ! kind ! jvalue() } }
